def get_report_strings(language: str = "es") -> dict:
    lang = (language or "es").lower()[:2]
    return REPORT_STRINGS.get(lang, REPORT_STRINGS["es"])


def format_delta_display(absolute_delta, relative_delta) -> str:
    """Deterministic delta formatting (e.g. '+12 (+24.5%)' or '—')."""
    if absolute_delta is None and relative_delta is None:
        return "—"
    parts = []
    if absolute_delta is not None:
        sign = "+" if absolute_delta > 0 else ""
        parts.append(f"{sign}{absolute_delta}")
    if relative_delta is not None:
        rel_pct = relative_delta * 100
        sign = "+" if rel_pct > 0 else ""
        parts.append(f"({sign}{rel_pct:.1f}%)")
    return " ".join(parts) if parts else "—"
